<div class="card"><div class="card-header section-card-header"><span class="section-card-icon"><i class="mdi mdi-swap-vertical"></i></span><span>Riwayat pergerakan stok</span></div><div class="card-body table-responsive"><table id="stockTable" class="table align-middle w-100"><thead><tr><th>Waktu</th><th>Produk</th><th>Jenis</th><th>Jumlah</th><th>Sebelum</th><th>Sesudah</th><th>Petugas</th><th>Catatan</th></tr></thead></table></div></div>
<div class="modal fade" id="stockModal" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><form class="modal-content" id="stockForm"><div class="modal-header"><div class="fw-bold">Penyesuaian Stok</div><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="mb-2"><label class="form-label">Produk</label><select class="form-select" name="product_id"><option value="">Pilih produk</option>@foreach($products as $product)<option value="{{ $product->id }}">{{ $product->code }} · {{ $product->name }} ({{ $product->stock }})</option>@endforeach</select><div class="field-error" data-error="product_id"></div></div><div class="row g-2"><div class="col-6"><label class="form-label">Jenis</label><select class="form-select" name="type"><option value="in">Barang masuk</option><option value="adjustment">Set stok akhir</option></select></div><div class="col-6"><label class="form-label">Jumlah / stok akhir</label><input class="form-control" type="number" min="0" name="quantity"><div class="field-error" data-error="quantity"></div></div><div class="col-12"><label class="form-label">Catatan</label><textarea class="form-control" name="notes"></textarea><div class="field-error" data-error="notes"></div></div></div></div><div class="modal-footer"><button type="button" class="btn btn-light" data-bs-dismiss="modal">Batal</button><button class="btn btn-primary" id="saveStock">Simpan</button></div></form></div></div>
