@push('scripts')<script>
$(function(){const url=@json(route('stocks.index'));const modal=bootstrap.Modal.getOrCreateInstance('#stockModal');const table=$('#stockTable').DataTable({ajax:{url,dataSrc:'data'},order:[[0,'desc']],columns:[{data:'created_at',render:v=>new Date(v).toLocaleString('id-ID')},{data:'product.name',render:escapeHtml},{data:'type',render:v=>v==='in'?'Barang masuk':v==='out'?'Penjualan':'Penyesuaian'},{data:'quantity'},{data:'stock_before'},{data:'stock_after'},{data:'user.name',defaultContent:'Sistem',render:escapeHtml},{data:'notes',defaultContent:'-',render:escapeHtml}]});$('#adjustStock').click(()=>{$('#stockForm')[0].reset();clearErrors('#stockForm');modal.show()});$('#stockForm').submit(function(e){e.preventDefault();const b=$('#saveStock');buttonLoading(b,true);$.post(url,$(this).serialize()).done(r=>{modal.hide();table.ajax.reload();notify(r.message)}).fail(x=>{showErrors('#stockForm',x.responseJSON?.errors);notify(x.responseJSON?.message||'Gagal memperbarui stok.',false)}).always(()=>buttonLoading(b,false))});});
</script>@endpush
